import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'mock-probe',
  description:
    'Probe the live fake calendar service for this eval: fetches the weekly events and returns the raw JSON as evidence for the plan.',
  inputs: {},
  outputs: {
    events: { type: 'string', description: 'Raw JSON body from the week events listing.' },
  },
  requires: ['workspace.read', 'network', 'credential:mock.calendar'],
});

const services = JSON.parse(await gezel.fs.read('mocks/services.json'));
const base = (id) => {
  const service = services.find((entry) => entry.id === id);
  if (!service) throw new Error(`mock service "${id}" is not listed in mocks/services.json`);
  return service.baseUrl;
};

const events = await gezel.http.authed(`${base('calendar')}/api/events`, {
  credential: 'mock.calendar',
});
if (!events.ok) throw new Error(`events listing failed: ${events.status} ${events.body}`);

gezel.output({ events: events.body });
